// Data shape: ordered list of numbers, indexes 0..2
const scores = [12, 7, 30];

console.log(scores[0]);     // 12
console.log(scores.length); // 3
console.log(Array.isArray(scores)); // true

// A literal can hold mixed values, but a single type is easier to work with
const mixed = ['Vienna', 4, true];

// Data shape: string, Set, or array-like input
const letters = Array.from('abc');            // ['a', 'b', 'c']
const unique = Array.from(new Set([1, 1, 2])); // [1, 2]

// Second argument maps while building, index included
const even = Array.from({ length: 4 }, (_, index) => index * 2);
console.log(even); // [0, 2, 4, 6]

// Data shape: one value becomes one element
console.log(Array.of(7));       // [7]
console.log(Array.of(7, 8, 9)); // [7, 8, 9]

// The trap this avoids:
console.log(new Array(7).length); // 7, but the array is empty of values
console.log(Array.of(7).length);  // 1

// Data shape: ordered list of stops
const stops = ['A', 'B', 'C'];

console.log(stops.at(0));   // 'A'
console.log(stops.at(-1));  // 'C', the last element
console.log(stops.at(-2));  // 'B'
console.log(stops.at(9));   // undefined, no error

// The old form still works and still needs the arithmetic:
console.log(stops[stops.length - 1]); // 'C'

// Data shape: list of guest names
const guests = ['Ana', 'Bela'];

const size = guests.push('Csilla');
console.log(size);   // 3, the return value is a number
console.log(guests); // ['Ana', 'Bela', 'Csilla']

// Several values at once, in argument order
guests.push('Dora', 'Emil');
console.log(guests.length); // 5

// Data shape: stack of page names
const stack = ['home', 'hotels', 'detail'];

const last = stack.pop();
console.log(last);  // 'detail'
console.log(stack); // ['home', 'hotels']

console.log([].pop()); // undefined, no throw

// A stack loop that stops on the empty case
while (stack.length > 0) {
  console.log(stack.pop());
}

// Data shape: queue of ticket ids
const queue = [101, 102, 103];

const first = queue.shift();
console.log(first); // 101
console.log(queue); // [102, 103]

console.log([].shift()); // undefined

// A queue drain
while (queue.length > 0) {
  console.log(queue.shift());
}

// Data shape: list of recent searches, newest first
const recent = ['Graz'];

const size = recent.unshift('Vienna');
console.log(size);   // 2
console.log(recent); // ['Vienna', 'Graz']

recent.unshift('Linz', 'Salzburg');
console.log(recent); // ['Linz', 'Salzburg', 'Vienna', 'Graz']

// Data shape: ordered list of stop names
const stops = ['A', 'B', 'C', 'D'];

const removed = stops.splice(1, 2);
console.log(removed); // ['B', 'C']
console.log(stops);   // ['A', 'D']

// Insert without deleting
stops.splice(1, 0, 'X', 'Y');
console.log(stops); // ['A', 'X', 'Y', 'D']

// Negative start counts from the end
stops.splice(-1, 1);
console.log(stops); // ['A', 'X', 'Y']

// Data shape: list of scores in order
const scores = [10, 20, 30, 40, 50];

console.log(scores.slice(1, 3)); // [20, 30]
console.log(scores.slice(2));    // [30, 40, 50]
console.log(scores.slice(-2));   // [40, 50]
console.log(scores.slice());     // full shallow copy
console.log(scores.slice(3, 1)); // []

scores.slice(0, 2)[0] = 99;
console.log(scores[0]); // 10, the copy was separate

// Data shape: two lists of tags
const a = ['red', 'green'];
const b = ['blue'];

console.log(a.concat(b));     // ['red', 'green', 'blue']
console.log(a);               // ['red', 'green'], unchanged
console.log(a.concat(b, ['x'])); // three groups appended

// Nested arrays are not flattened
console.log([1].concat([2, [3]])); // [1, 2, [3]]

// The spread form most code uses now
console.log([...a, ...b]); // ['red', 'green', 'blue']

// Data shape: list of city names
const cities = ['Vienna', 'Graz', 'Linz'];

console.log(cities.join(', ')); // 'Vienna, Graz, Linz'
console.log(cities.join(' | ')); // 'Vienna | Graz | Linz'
console.log(cities.join(''));    // 'ViennaGrazLinz'

// Missing values become empty text
console.log([1, null, 3].join('-')); // '1--3'
console.log([].join(','));           // ''

// Data shape: list of room numbers
const rooms = [101, 205, 309];

console.log(rooms.includes(205)); // true
console.log(rooms.includes(999)); // false

// NaN is found, unlike with indexOf
console.log([NaN].includes(NaN)); // true
console.log([NaN].indexOf(NaN));  // -1

// Objects are compared by reference, not by content
const a = { hotel_id: 1 };
console.log([a].includes({ hotel_id: 1 })); // false
console.log([a].includes(a));               // true

// Data shape: list of hotel ids
const ids = [10, 11, 12, 11];

console.log(ids.indexOf(11));      // 1, first match only
console.log(ids.indexOf(11, 2));   // 3, start searching at index 2
console.log(ids.indexOf(99));      // -1

// The -1 result is a common bug when used as an index
const position = ids.indexOf(99);
console.log(ids[position]); // undefined

if (position !== -1) {
  console.log('found at', position);
}

// Data shape: list of booking objects
const bookings = [
  { booking_id: 1, city: 'Vienna', adults: 2 },
  { booking_id: 2, city: 'Graz', adults: 1 },
];

const found = bookings.find((item) => item.city === 'Graz');
console.log(found); // { booking_id: 2, city: 'Graz', adults: 1 }

console.log(bookings.find((item) => item.city === 'Linz')); // undefined

// Guard before reading a property
const linz = bookings.find((item) => item.city === 'Linz');
console.log(linz?.booking_id); // undefined, no throw

// Data shape: list of hotel objects
const hotels = [
  { name: 'Ring', stars: 5 },
  { name: 'Park', stars: 3 },
];

const position = hotels.findIndex((hotel) => hotel.name === 'Park');
console.log(position); // 1

console.log(hotels.findIndex((hotel) => hotel.name === 'Garden')); // -1

// Remove the found record with splice
if (position !== -1) {
  hotels.splice(position, 1);
}
console.log(hotels.length); // 1

// Data shape: list of booking objects with a total
const bookings = [
  { booking_id: 1, total: 480, city: 'Vienna' },
  { booking_id: 2, total: 150, city: 'Graz' },
  { booking_id: 3, total: 910, city: 'Vienna' },
];

const big = bookings.filter((item) => item.total >= 480);
console.log(big.length); // 2
console.log(big.map((item) => item.booking_id)); // [1, 3]

const vienna = bookings.filter((item) => item.city === 'Vienna');
console.log(vienna.length); // 2

console.log(bookings.length); // 3, the input is untouched

// Data shape: list of prices in euros
const prices = [40, 15, 90];

const withTax = prices.map((price) => price * 1.2);
console.log(withTax); // [48, 18, 108]
console.log(prices);  // [40, 15, 90], unchanged

// Reshape objects, keeping only what is needed
const hotels = [
  { hotel_id: 1, name: 'Ring', stars: 5 },
  { hotel_id: 2, name: 'Park', stars: 3 },
];
const labels = hotels.map((hotel) => `${hotel.name} (${hotel.stars})`);
console.log(labels); // ['Ring (5)', 'Park (3)']

// Index is available as the second argument
console.log(prices.map((price, index) => index + ':' + price));

// Data shape: array of booking totals in euros
const totals = [240, 120, 380];

const sum = totals.reduce((acc, value) => acc + value, 0);
console.log(sum); // 740

// The accumulator can be any type, here an object
const cities = ['Vienna', 'Graz', 'Vienna'];
const counts = cities.reduce((acc, city) => {
  acc[city] = (acc[city] || 0) + 1;
  return acc;
}, {});
console.log(counts); // { Vienna: 2, Graz: 1 }

// Max without sorting
const max = totals.reduce((acc, value) => Math.max(acc, value), 0);
console.log(max); // 380

// Data shape: list of booking objects
const bookings = [
  { adults: 2, children: 0 },
  { adults: 1, children: 2 },
];

console.log(bookings.some((item) => item.children > 0)); // true
console.log(bookings.some((item) => item.adults > 5));   // false

// Empty array: no element can pass
console.log([].some((value) => value > 0)); // false

// Early exit is visible in the log
[1, 2, 3].some((value) => {
  console.log('check', value);
  return value === 2;
}); // logs 1 and 2 only

// Data shape: list of hotel objects
const hotels = [
  { name: 'Ring', stars: 5 },
  { name: 'Park', stars: 3 },
];

console.log(hotels.every((hotel) => hotel.stars >= 3)); // true
console.log(hotels.every((hotel) => hotel.stars === 5)); // false

// Empty array: vacuously true
console.log([].every((hotel) => hotel.stars > 5)); // true

// Guard a form before sending it
const valid = hotels.every((hotel) => hotel.name && hotel.stars > 0);
console.log(valid); // true

// Data shape: list of numbers
const numbers = [10, 9, 1, 100];

console.log([...numbers].sort()); // [1, 10, 100, 9], string order
console.log([...numbers].sort((a, b) => a - b)); // [1, 9, 10, 100]

// Objects by one key, highest first
const hotels = [
  { name: 'Ring', stars: 5 },
  { name: 'Park', stars: 3 },
  { name: 'Garden', stars: 4 },
];

const ranked = [...hotels].sort((a, b) => b.stars - a.stars);
console.log(ranked.map((hotel) => hotel.name)); // ['Ring', 'Garden', 'Park']

console.log(numbers); // [10, 9, 1, 100], the copy above kept it intact

// Data shape: list of guest names
const guests = ['Ana', 'Bela', 'Csilla'];

const result = guests.forEach((name, index) => {
  console.log(index, name);
});
console.log(result); // undefined

// Accumulate into an outside variable when that is the goal
let total = 0;
[10, 20, 30].forEach((value) => {
  total += value;
});
console.log(total); // 60

// Data shape: hotels, each with a bookings array
const hotels = [
  { name: 'Ring', bookings: [{ total: 100 }, { total: 200 }] },
  { name: 'Park', bookings: [{ total: 50 }] },
];

const totals = hotels.flatMap((hotel) =>
  hotel.bookings.map((booking) => booking.total)
);
console.log(totals); // [100, 200, 50]

// One level only, deeper nesting stays
console.log([[1], [[2]]].flatMap((value) => value)); // [1, [2]]
